BEGIN; DROP MATERIALIZED VIEW IF EXISTS popular_products_cache; CREATE MATERIALIZED VIEW popular_products_cache AS SELECT product_id, product_name, product_image, SUM(quantity) as total_ordered FROM order_items WHERE product_type = 'capsule' GROUP BY product_id, product_name, product_image; CREATE INDEX IF NOT EXISTS idx_popular_products_total ON popular_products_cache(total_ordered DESC); COMMIT;
